# Feasibility and active-constraint dual certificate of the saved LP vertices;
# no optimizer or candidate search/refit is invoked.
import sys,json,collections,itertools,hashlib
from pathlib import Path
from fractions import Fraction as F
sys.path.insert(0,'bench')
import two_fe_policy_calibrate as c,two_fe_policy_fit as m
p=Path('target/tmp/cmg-upgrade/policy');raw=json.loads((p/'fit.json').read_text())
def de(x):
 if isinstance(x,dict):return F(x['numerator'],x['denominator']) if set(x)=={'numerator','denominator'} else {k:de(v) for k,v in x.items()}
 if isinstance(x,list):return [de(y) for y in x]
 return x
f=de(raw);rows=[c.label_row(o) for o in f['observations']];co=m.Coefficients(**f['coefficients']);e=[m.exposures(r.structure,r.execution) for r in rows];j=[m.iteration(co,x,r.execution.workers) for r,x in zip(rows,e)];a=[m.up(co.a_0,x.Z) for x in e];startup=[r.execution.r*y for r,y in zip(rows,a)]
stages=[(('i_s','i_p'),[(r.work.H*x.V,F(r.work.H*x.O,r.execution.workers)) for r,x in zip(rows,e)],'incumbent_ns',False),(('b_s','b_p'),[(x.S,F(x.P,r.execution.workers)) for r,x in zip(rows,e)],'setup_ns',True),(('a_0',),[(r.execution.r*x.Z,) for r,x in zip(rows,e)],'startup_ns',True),(('r_0',),[(x.O+x.V,) for x in e],'restart_ns',True),(('t_0','t_1'),[(jj+ss,r.work.H*jj+aa*r.work.D) for r,jj,ss,aa in zip(rows,j,startup,a)],'continuation_ns',True)]
counts=collections.Counter(r.cell for r in rows)
for names,features,label,upper in stages:
 theta=tuple(f['rational'][n] for n in names);dim=len(theta);g=tuple(sum(F(x[k],counts[r.cell]) for x,r in zip(features,rows)) for k in range(dim));active=[]
 for x,r in zip(features,rows):
  y=F(11 if upper else 9,10)*getattr(r,label);pred=sum(t*v for t,v in zip(theta,x));assert pred>=y if upper else pred<=y
  if pred==y:active.append(tuple(map(F,x)))
 for k,t in enumerate(theta):
  if t==0:active.append(tuple(F((1 if upper else -1) if n==k else 0) for n in range(dim)))
 active=list(set(active));ok=False
 if dim==1:ok=any(x[0] and g[0]/x[0]>=0 for x in active)
 else:
  for x in active:
   k=next((k for k in range(dim) if x[k]),None)
   if k is not None and g[k]/x[k]>=0 and all(g[z]==g[k]/x[k]*x[z] for z in range(dim)):ok=True
  for x,y in itertools.combinations(active,2):
   det=x[0]*y[1]-x[1]*y[0]
   if det and (g[0]*y[1]-g[1]*y[0])/det>=0 and (x[0]*g[1]-x[1]*g[0])/det>=0:ok=True
 assert ok,names
 print('saved optimality certified',names,'activeconstraints',len(active))
cp=json.loads((p/'cross-platform.json').read_text());assert cp['checker_sha256']==hashlib.sha256(Path('target/tmp/cmg-upgrade/check-policy-platforms.py').read_bytes()).hexdigest()
results={x:json.loads((p/f'results-{x}/run-0-0/results.json').read_text()) for x in ('Darwin','Linux')}
for x in results:assert cp['result_sha256'][x]==hashlib.sha256((p/f'results-{x}/run-0-0/results.json').read_bytes()).hexdigest()
for a,b in zip(results['Darwin']['cases'],results['Linux']['cases']):
 assert a['id']==b['id'] and a['worker_signatures']==b['worker_signatures']
 for x,y in zip(a['warmups'],b['warmups']):
  for k in ('execution','fingerprint','route_trace','route_hierarchy'):assert x[k]==y[k]
print('crossplatform288 warmup fingerprint/route/hierarchy/discrete pairs exact; checker/result hashes bound')
